52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private static final org.slf4j.Logger NOTIFY = org.slf4j.LoggerFactory.getLogger("NOTIFY");
60	
61	    /**
62	     * Monotonically increasing sequence assigned to each {@code OWNER_CREATED} structured event, in
63	     * the order owners are created across this application instance. Shared across all requests.
64	     */
65	    private static final java.util.concurrent.atomic.AtomicLong OWNER_EVENT_SEQ =
66	        new java.util.concurrent.atomic.AtomicLong();
67	
68	    /** Serializes the immutable {@link OwnerCreatedEvent} to its canonical JSON form. */
69	    private static final tools.jackson.databind.ObjectMapper AUDIT_EVENT_MAPPER =
70	        tools.jackson.databind.json.JsonMapper.builder().build();
71	
72	    /**
73	     * The schema version of the structured {@code OWNER_CREATED} audit event. Version 2 accompanies
74	     * the version-2 owner identity: the event carries the version-2 {@code memberId} as its primary
75	     * identifier and adds the {@code schemaVersion} field.
76	     */
77	    private static final int AUDIT_EVENT_SCHEMA_VERSION = 2;
78	
79	    /**
80	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
81	     * is created. Its component order is also its JSON field order: {@code schemaVersion}, {@code seq},
82	     * {@code ownerId}, {@code memberId}, {@code membershipLevel}, {@code ownerSegment}, {@code event}.
83	     * This is schema version 2: {@code schemaVersion} is {@code 2}, the {@code memberId} component
84	     * carries the owner's version-2 unified primary identifier, and {@code ownerSegment} is the owner
85	     * segment recomputed from the version-2 identity.
86	     */
87	    private record OwnerCreatedEvent(int schemaVersion, long seq, Integer ownerId, String memberId,
88	        Integer membershipLevel, String ownerSegment, String event) {
89	    }
90	
91	    /**
92	     * Remembers, per seen {@code Idempotency-Key} header, the id of the owner originally created for
93	     * that key, so a repeated create carrying the same key returns that owner instead of creating a
94	     * duplicate. Kept in memory and keyed on the opaque client-supplied value.
95	     */
96	    private static final java.util.Map<String, Integer> IDEMPOTENCY_KEYS =
97	        new java.util.concurrent.ConcurrentHashMap<>();
98	
99	    private final ClinicService clinicService;
100	
101	    private final OwnerMapper ownerMapper;
102	
103	    private final PetMapper petMapper;
104	
105	    private final VisitMapper visitMapper;
