132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already seen, return
146	        // the owner originally created for that key with 200 OK, rather than creating a duplicate (which
147	        // the identity/household duplicate rules would otherwise reject with 409).
148	        String idempotencyKey = currentIdempotencyKey();
149	        if (idempotencyKey != null) {
150	            Integer existingId = IDEMPOTENCY_KEYS.get(idempotencyKey);
151	            if (existingId != null) {
152	                Owner existing = this.clinicService.findOwnerById(existingId);
153	                if (existing != null) {
154	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
155	                }
156	            }
157	        }
158	        HttpHeaders headers = new HttpHeaders();
159	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
160	        applyAddress(owner);
161	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
162	        owner.setTelephone(normalizedTelephone);
163	        owner.setEmail(normalizeEmail(owner.getEmail()));
164	        validateEmailDomain(owner.getEmail());
165	        validatePostcode(owner.getPostcode(), owner.getCity());
166	        java.time.LocalDate serverDate = java.time.LocalDate.now();
167	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
168	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
169	                "Registration date must not be later than the current server date");
170	        }
171	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
172	            ? owner.getRegistrationDate() : serverDate;
173	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
174	        owner.setRegistrationDate(businessDate);
175	        long createdToday = this.clinicService.findAllOwners().stream()
176	            .map(Owner::getRegistrationDate)
177	            .filter(businessDate::equals)
178	            .count();
179	        if (createdToday >= 100) {
180	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
181	                "The maximum number of owners for today has already been reached");
182	        }
183	        owner.setBulkSignupWarning(createdToday > 80);
184	        // The household is keyed deterministically on (normalized last name, postcode): every owner
185	        // computes the same householdId from those two fields, so owners sharing a last name and
186	        // postcode belong to the same household automatically, without any explicit linking.
187	        String lastNameKey = normalizeForHousehold(owner.getLastName());
188	        String householdId = householdId(lastNameKey, owner.getPostcode());
189	        owner.setHouseholdId(householdId);
190	        // Soft-deleted owners are excluded from all duplicate/identity detection: a deleted owner
191	        // no longer blocks a new owner that would otherwise match it.
192	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> !existing.isDeleted())
194	            .filter(existing -> householdId.equals(
195	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
196	            .toList();
197	        // All duplicate detection is expressed through the single derived identityKey, the SHA-256
198	        // hex of (normalizedTelephone|lowerEmail|soundex(lastName)); a new owner is rejected only
199	        // when its whole key matches an existing (non-deleted) owner's.
200	        String identityKey = owner.getIdentityKey();
201	        boolean identityInUse = this.clinicService.findAllOwners().stream()
202	            .filter(existing -> !existing.isDeleted())
203	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
204	        if (identityInUse) {
205	            throw new ResponseStatusException(HttpStatus.CONFLICT,
206	                "An owner with this identity already exists");
207	        }
208	        // Duplicate detection is now the single identity key above; because the telephone is part of
209	        // that key, two owners sharing a last name and postcode but with different telephones have
210	        // different keys and are both admitted, so the former household-duplicate 409 no longer
211	        // applies. Declaring 'sharesHousehold' marks the new owner as a declared household member.
212	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
213	        // An undeclared new owner joining an existing household while carrying its own (distinct)
214	        // email address joins as a member whose membership level is capped below.
215	        boolean distinguishableByEmail = owner.getEmail() != null && !owner.getEmail().isBlank()
216	            && householdMembers.stream()
217	                .noneMatch(existing -> owner.getEmail().equalsIgnoreCase(existing.getEmail()));
218	        boolean joinsExistingHousehold = !householdMembers.isEmpty()
219	            && !declaredHouseholdMember && distinguishableByEmail;
220	        String cityKey = normalizeForHousehold(owner.getCity());
221	        long cityCount = this.clinicService.findAllOwners().stream()
222	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
223	            .count();
224	        if (cityCount >= 50) {
225	            throw new ResponseStatusException(HttpStatus.CONFLICT,
226	                "This city already has the maximum number of owners");
227	        }
228	        // Approaching the per-city capacity limit (50): warn once the city already holds 40-49
229	        // owners. Fixed at creation time, mirroring bulkSignupWarning. The >= 50 case is rejected
230	        // above, so cityCount is guaranteed below 50 here.
231	        owner.setCapacityWarning(cityCount >= 40);
232	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
233	        owner.setHouseholdSize(householdMembers.size() + 1);
234	        // A new owner joining an existing household cannot rank more than one level above the current
235	        // maximum membership level among their household members: its level is capped there. With no
236	        // existing household member (the usual case) no cap applies and the level stays as derived.
237	        if (joinsExistingHousehold) {
238	            int naturalLevel = Owner.membershipLevel(Owner.membershipPoints(owner));
239	            int maxMemberLevel = householdMembers.stream()
240	                .mapToInt(Owner::effectiveMembershipLevel)
241	                .max().orElse(0);
242	            owner.setMembershipLevel(Math.min(naturalLevel, maxMemberLevel + 1));
243	        }
244	        // Soft match: a new owner whose identityKey differs from every existing owner but whose
245	        // soundex(lastName) and postcode both match an existing (non-deleted) owner is flagged as a
246	        // possible duplicate of the earliest such owner. Soft-deleted owners are ignored, matching
247	        // the identity check above.
248	        String lastNameSoundex = Owner.soundex(owner.getLastName());
249	        Owner softMatch = this.clinicService.findAllOwners().stream()
250	            .filter(existing -> !existing.isDeleted())
251	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
252	            .filter(existing -> owner.getPostcode() != null
253	                && owner.getPostcode().equals(existing.getPostcode()))
254	            .filter(existing -> lastNameSoundex.equals(Owner.soundex(existing.getLastName())))
255	            .min(java.util.Comparator.comparing(Owner::getId))
256	            .orElse(null);
257	        if (softMatch != null) {
258	            owner.setPossibleDuplicate(true);
259	            owner.setPossibleDuplicateOf(softMatch.getId());
260	        } else {
261	            owner.setPossibleDuplicate(false);
262	            owner.setPossibleDuplicateOf(null);
263	        }
264	        owner.setMemberId(deduplicateMemberId(memberId(owner.getCity(), owner.getPostcode(),
265	            owner.getTelephone(), owner.getLastName(), owner.getRegistrationDate())));
266	        this.clinicService.saveOwner(owner);
267	        if (idempotencyKey != null) {
268	            IDEMPOTENCY_KEYS.put(idempotencyKey, owner.getId());
269	        }
270	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
271	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
272	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
273	        // The event's primary identifier is the owner's version-2 unified memberId, and its
274	        // ownerSegment is recomputed from the version-2 identity.
275	        String primaryIdentifier = owner.getMemberId();
276	        String ownerSegment = org.springframework.samples.petclinic.mapper.Localities
277	            .segmentForOwner(owner);
278	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SCHEMA_VERSION,
279	            OWNER_EVENT_SEQ.incrementAndGet(), owner.getId(), primaryIdentifier,
280	            ownerDto.getMembershipLevel(), ownerSegment, "OWNER_CREATED");
281	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
282	        // Enqueue a welcome notification for the newly created owner, carrying the owner id and the
283	        // unified memberId so downstream notification handling can address the new member.
284	        NOTIFY.info("Welcome notification enqueued: ownerId={} memberId={}",
285	            owner.getId(), owner.getMemberId());
286	        headers.setLocation(UriComponentsBuilder.newInstance()
287	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
288	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
289	    }
290	
291	    /**
292	     * Reads the current request's {@code Idempotency-Key} header, if any. Returns the trimmed header
293	     * value, or {@code null} when the header is absent, blank, or there is no active request (so a
294	     * request without the header behaves exactly as before).
295	     *
296	     * @return the non-blank idempotency key for the current request, or {@code null}
297	     */
298	    private String currentIdempotencyKey() {
299	        org.springframework.web.context.request.RequestAttributes attrs =
300	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
301	        if (!(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs)) {
302	            return null;
303	        }
304	        String key = servletAttrs.getRequest().getHeader("Idempotency-Key");
305	        if (key == null || key.isBlank()) {
306	            return null;
307	        }
308	        return key.trim();
309	    }
310	
311	    /**
312	     * The fixed public-holiday calendar the business-day roll skips. When an adjusted registration
313	     * date lands on one of these dates it is rolled forward to the next non-holiday business day.
314	     */
315	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
316	        java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
317	        java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
318	        java.time.LocalDate.parse("2026-12-28"));
319	
320	    /**
321	     * Rolls a registration date forward to a business day. A Saturday, Sunday or listed public
322	     * holiday is advanced one day at a time until it lands on a weekday that is not a public holiday;
323	     * a plain weekday is returned unchanged. This is applied to the effective registration date
324	     * (whether supplied in the request or defaulted to the server date) so that every stored
325	     * {@code registrationDate}, and any value derived from it, lands on a business day.
326	     *
327	     * @param date the effective registration date
328	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
329	     */
330	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
331	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
332	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
333	            || PUBLIC_HOLIDAYS.contains(date)) {
334	            date = date.plusDays(1);
335	        }
336	        return date;
337	    }
338	
339	    /**
340	     * Counts the owners that already exist (before the current create) whose first and last names
341	     * both match the supplied names, compared case-insensitively. The returned value is captured on
342	     * the new owner at creation time and does not change as further owners are added later.
343	     *
344	     * @param firstName the new owner's first name
345	     * @param lastName  the new owner's last name
346	     * @return the number of pre-existing namesake owners
347	     */
348	    private int namesakeCount(String firstName, String lastName) {
349	        return (int) this.clinicService.findAllOwners().stream()
350	            .filter(existing -> existing.getFirstName() != null
351	                && existing.getFirstName().equalsIgnoreCase(firstName)
352	                && existing.getLastName() != null
353	                && existing.getLastName().equalsIgnoreCase(lastName))
354	            .count();
355	    }
356	
357	    /**
358	     * Builds the unified member id for a new owner, formatted {@code '<REGION><FY><HASH8><CHK>'}.
359	     * {@code REGION} is the version-2 region code — the canonical region derived from the owner's
360	     * postcode (falling back to the city when the postcode is absent or in no known range) with the
361	     * fixed {@code 'V2'} version tag mixed in, see
362	     * {@link org.springframework.samples.petclinic.mapper.Localities#regionCodeV2}.
363	     * {@code FY} is the 2-digit fiscal year of the (business-day-adjusted) registration date.
364	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
365	     * normalized telephone concatenated with the last name (the same HASH8 the region-and-hash
366	     * identity used). {@code CHK} is a single Luhn check digit computed over the digits of the
367	     * {@code <REGION><FY><HASH8>} prefix (e.g. {@code 'V2NSW261A2B3C4D7'}). It is a pure function of
368	     * the owner's region, fiscal year, telephone and last name.
369	     *
370	     * @param city                the owner's city
371	     * @param postcode            the owner's postcode, may be {@code null}
372	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
373	     * @param lastName            the owner's last name
374	     * @param registrationDate    the owner's business-day-adjusted registration date
375	     * @return the assigned member id
376	     */
377	    private String memberId(String city, String postcode, String normalizedTelephone, String lastName,
378	            java.time.LocalDate registrationDate) {
379	        String region = org.springframework.samples.petclinic.mapper.Localities
380	            .regionCodeV2(city, postcode);
381	        String fy = Owner.fiscalYearLabel(registrationDate).substring(2);
382	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
383	            + (lastName == null ? "" : lastName), 8);
384	        String prefix = region + fy + hash8;
385	        return prefix + Owner.luhnCheckDigit(prefix);
386	    }
387	
388	    /**
389	     * Ensures the computed {@code memberId} is unique across existing owners. When {@code baseId}
390	     * does not collide with any existing owner's {@code memberId} it is returned unchanged.
391	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
392	     * value not already in use, and that de-duplicated id is returned.
393	     *
394	     * @param baseId the freshly computed member id
395	     * @return {@code baseId} if unused, otherwise {@code baseId + "-" + n} for the smallest free n
396	     */
397	    private String deduplicateMemberId(String baseId) {
398	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
399	            .map(org.springframework.samples.petclinic.model.Owner::getMemberId)
400	            .filter(java.util.Objects::nonNull)
401	            .collect(java.util.stream.Collectors.toSet());
402	        if (!inUse.contains(baseId)) {
403	            return baseId;
404	        }
405	        int n = 2;
406	        while (inUse.contains(baseId + "-" + n)) {
407	            n++;
408	        }
409	        return baseId + "-" + n;
410	    }
411	
412	    /**
413	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
414	     * UTF-8 bytes of {@code value}.
415	     *
416	     * @param value  the source value to hash
417	     * @param length the number of leading hex characters to return
418	     * @return the leading upper-case hex characters of the digest
419	     */
420	    private String sha256UpperHex(String value, int length) {
421	        try {
422	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
423	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
424	            StringBuilder sb = new StringBuilder(digest.length * 2);
425	            for (byte b : digest) {
426	                sb.append(String.format("%02x", b));
427	            }
428	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
429	        }
430	        catch (java.security.NoSuchAlgorithmException e) {
431	            throw new IllegalStateException("SHA-256 not available", e);
432	        }
433	    }
434	
435	    /**
436	     * Normalizes a street address applied whenever an owner is created: leading and trailing
437	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
438	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
439	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
440	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
441	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
442	     * {@code '12 MAIN STREET'}.
443	     *
444	     * @param address the raw address as submitted, or {@code null} when absent
445	     * @return the normalized address, or the empty string when the value is blank
446	     */
447	    /**
448	     * Resolves and normalizes an owner's postal address, accepting either the structured form
449	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
450	     * input for backward compatibility. The structured form is preferred: when a non-blank
451	     * {@code addressLine1} is supplied, both structured lines are normalized (see
452	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
453	     * the normalized {@code addressLine1}, with a single space and the normalized
454	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
455	     * {@code address} input is normalized and stored, and the structured lines are cleared.
456	     *
457	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
458	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
459	     *
460	     * @param owner the owner whose address fields are resolved and normalized in place
461	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
462	     */
463	    private void applyAddress(Owner owner) {
464	        String line1 = normalizeAddress(owner.getAddressLine1());
465	        String line2 = normalizeAddress(owner.getAddressLine2());
466	        String flat = normalizeAddress(owner.getAddress());
467	        String composed;
468	        if (!line1.isEmpty()) {
469	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
470	            owner.setAddressLine1(line1);
471	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
472	        } else {
473	            composed = flat;
474	            owner.setAddressLine1(null);
475	            owner.setAddressLine2(null);
476	        }
477	        if (composed.isEmpty()) {
478	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
479	                "Address must not be blank after normalization");
480	        }
481	        owner.setAddress(composed);
482	    }
483	
484	    private String normalizeAddress(String address) {
485	        String collapsed = (address == null ? "" : address)
486	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
487	        if (collapsed.isEmpty()) {
488	            return "";
489	        }
490	        String[] tokens = collapsed.split(" ");
491	        for (int i = 0; i < tokens.length; i++) {
492	            switch (tokens[i]) {
493	                case "ST" -> tokens[i] = "STREET";
494	                case "RD" -> tokens[i] = "ROAD";
495	                case "AVE" -> tokens[i] = "AVENUE";
496	                default -> { }
497	            }
498	        }
499	        return String.join(" ", tokens);
500	    }
