502	    /**
503	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
504	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
505	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
506	     * empty string.
507	     *
508	     * @param value the raw value (last name or address) as submitted
509	     * @return the normalized comparison key
510	     */
511	    private String normalizeForHousehold(String value) {
512	        if (value == null) {
513	            return "";
514	        }
515	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
516	    }
517	
518	    /**
519	     * Derives the stable shared household identifier for a household, keyed on the normalized last
520	     * name and postcode. Because it is a pure function of those normalized keys, every owner in the
521	     * same household deterministically computes the same value. The identifier is the first 12
522	     * upper-case hex characters of the SHA-256 digest of the fixed {@code 'V2'} version tag and the
523	     * two keys joined with {@code '|'} separators (the separators prevent distinct pairs from
524	     * colliding, and mixing in the version tag rederives the value under version 2).
525	     *
526	     * @param lastNameKey the normalized last-name comparison key
527	     * @param addressKey  the normalized address comparison key
528	     * @return the stable household identifier
529	     */
530	    private String householdId(String lastNameKey, String postcode) {
531	        String seed = Owner.IDENTITY_VERSION_TAG + "|" + lastNameKey + "|"
532	            + (postcode == null ? "" : postcode);
533	        try {
534	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
535	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
536	            StringBuilder sb = new StringBuilder(digest.length * 2);
537	            for (byte b : digest) {
538	                sb.append(String.format("%02x", b));
539	            }
540	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
541	        }
542	        catch (java.security.NoSuchAlgorithmException e) {
543	            throw new IllegalStateException("SHA-256 not available", e);
544	        }
545	    }
546	
547	    /**
548	     * The exact number of national (subscriber) digits required for a given country calling code,
549	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
550	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
551	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
552	     */
553	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
554	        java.util.Map.of("61", 9, "1", 10);
555	
556	    /**
557	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
558	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
559	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
560	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
561	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
562	     * is stored as {@code '+61412345678'}.
563	     *
564	     * <p>In addition, when the number's country code has a fixed national-number length (see
565	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
566	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
567	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
568	     *
569	     * @param telephone the raw telephone number as submitted
570	     * @return the normalized E.164 telephone number
571	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
572	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
573	     *         for its country code
574	     */
575	    private String normalizeTelephone(String telephone) {
576	        String raw = telephone == null ? "" : telephone.trim();
577	        String digits = raw.replaceAll("\\D", "");
578	        String e164;
579	        if (raw.startsWith("+")) {
580	            e164 = "+" + digits;
581	        } else {
582	            if (digits.startsWith("0")) {
583	                digits = digits.substring(1);
584	            }
585	            e164 = "+61" + digits;
586	        }
587	        int digitCount = e164.length() - 1;
588	        if (digitCount < 8 || digitCount > 15) {
589	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
590	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
591	        }
592	        validateNationalNumberLength(e164);
593	        return e164;
594	    }
595	
596	    /**
597	     * Validates that an E.164 number's national-number length is correct for its country code.
598	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
599	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
600	     * following it must match exactly. Country codes without a fixed length are left unchecked.
601	     *
602	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
603	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
604	     *         for the country code
605	     */
606	    private void validateNationalNumberLength(String e164) {
607	        String allDigits = e164.substring(1);
608	        String bestCode = null;
609	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
610	            if (allDigits.startsWith(code)
611	                    && (bestCode == null || code.length() > bestCode.length())) {
612	                bestCode = code;
613	            }
614	        }
615	        if (bestCode == null) {
616	            return;
617	        }
618	        int nationalLength = allDigits.length() - bestCode.length();
619	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
620	        if (nationalLength != required) {
621	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
622	                "Telephone for country code '+" + bestCode + "' must have " + required
623	                    + " national digits");
624	        }
625	    }
626	
627	    /**
628	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
629	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
630	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
631	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
632	     */
633	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
634	        "NSW", new int[] {2000, 2099},
635	        "VIC", new int[] {3000, 3099},
636	        "QLD", new int[] {4000, 4099});
637	
638	    /**
639	     * Validates an owner's optional postcode against their city's region. The postcode is only
640	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
641	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
642	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
643	     * postcode must fall within that region's inclusive range; a city with no known region accepts
644	     * any 4-digit postcode.
645	     *
646	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
647	     * @param city     the owner's city, used to derive the region whose range applies
648	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
649	     *         for the city's region
650	     */
651	    private void validatePostcode(String postcode, String city) {
652	        if (postcode == null) {
653	            return;
654	        }
655	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
656	        int[] range = REGION_POSTCODE_RANGES.get(region);
657	        if (range == null) {
658	            return;
659	        }
660	        int value = Integer.parseInt(postcode);
661	        if (value < range[0] || value > range[1]) {
662	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
663	                "Postcode " + postcode + " is not valid for region " + region);
664	        }
665	    }
666	
667	    /**
668	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
669	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
670	     * (absent) or already valid.
671	     *
672	     * @param email the email address as submitted, or {@code null} when absent
673	     * @return the lower-cased email, or {@code null} when absent
674	     */
675	    private String normalizeEmail(String email) {
676	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
677	    }
678	
679	    /**
680	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
681	     * providers are rejected because they cannot be relied on for durable contact.
682	     */
683	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
684	        "mailinator.com", "tempmail.com", "guerrillamail.com");
685	
686	    /**
687	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
688	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
689	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
690	     * (absent) is accepted, keeping the field optional.
691	     *
692	     * @param email the normalized email address, or {@code null} when absent
693	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
694	     */
695	    private void validateEmailDomain(String email) {
696	        if (email == null) {
697	            return;
698	        }
699	        int at = email.lastIndexOf('@');
700	        if (at < 0) {
701	            return;
702	        }
703	        String domain = email.substring(at + 1);
704	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
705	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
706	                "Email domain " + domain + " is not allowed");
707	        }
708	    }
