317	    /**
318	     * The owner's membership points, accumulated from the membership factors. Points start at 0 and
319	     * gain 2 when an email address is present, 1 when the owner has no namesakes (namesakeCount is
320	     * 0), 2 for a household of 3 or more members, and 3 when the owner's tenure exceeds one year.
321	     *
322	     * @param owner the owner to score
323	     * @return the total membership points (never negative)
324	     */
325	    public static int membershipPoints(Owner owner) {
326	        int points = 0;
327	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
328	            points += 2;
329	        }
330	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
331	            points += 1;
332	        }
333	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
334	            points += 2;
335	        }
336	        if (tenureExceedsOneYear(owner.getRegistrationDate())) {
337	            points += 3;
338	        }
339	        return points;
340	    }
