342	    /**
343	     * Maps membership points to the numeric membership level: 1 for 0-1 points, 2 for 2-3, 3 for
344	     * 4-5, and 4 for 6 or more.
345	     *
346	     * @param points the owner's membership points
347	     * @return the membership level, from 1 to 4
348	     */
349	    public static int membershipLevel(int points) {
350	        if (points <= 1) {
351	            return 1;
352	        }
353	        if (points <= 3) {
354	            return 2;
355	        }
356	        if (points <= 5) {
357	            return 3;
358	        }
359	        return 4;
360	    }
