468	        String seed = IDENTITY_VERSION_TAG + "|"
469	            + (this.telephone == null ? "" : this.telephone) + "|"
470	            + (this.email == null ? "" : this.email.toLowerCase(Locale.ROOT)) + "|"
471	            + soundex(this.getLastName());
472	        return sha256Hex(seed);
473	    }
