483	    /**
484	     * The registrable labels of the known disposable-mailbox providers. Exact provider domains
485	     * (e.g. {@code mailinator.com}) are already rejected at creation, so this set exists to catch
486	     * <em>disposable-adjacent</em> hosts that slip past that hard blocklist — subdomains
487	     * ({@code inbox.mailinator.com}) and alternate TLDs ({@code tempmail.io}) — by matching on the
488	     * provider label rather than the whole domain.
489	     */
490	    private static final Set<String> DISPOSABLE_PROVIDER_LABELS =
491	        Set.of("mailinator", "tempmail", "guerrillamail");
492	
493	    /**
494	     * Whether an email address's domain is <em>disposable-adjacent</em>: any dot-separated label of
495	     * the domain (the part after the last {@code '@'}) matches a known disposable-mailbox provider
496	     * label (see {@link #DISPOSABLE_PROVIDER_LABELS}), compared case-insensitively. This catches
497	     * throwaway hosts that are not on the hard blocklist because they are subdomains or use a
498	     * different TLD. A {@code null} email, or one without an {@code '@'}, is not adjacent.
499	     *
500	     * @param email the owner's (already normalized) email address, or {@code null} when absent
501	     * @return {@code true} when the email domain is disposable-adjacent
502	     */
503	    public static boolean emailDomainDisposableAdjacent(String email) {
504	        if (email == null) {
505	            return false;
506	        }
507	        int at = email.lastIndexOf('@');
508	        if (at < 0) {
509	            return false;
510	        }
511	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
512	        for (String label : domain.split("\\.")) {
513	            if (DISPOSABLE_PROVIDER_LABELS.contains(label)) {
514	                return true;
515	            }
516	        }
517	        return false;
518	    }
