535	    /**
536	     * The full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
537	     *
538	     * @param value the source value to hash
539	     * @return the 64-character lower-case hex digest
540	     */
541	    private static String sha256Hex(String value) {
542	        try {
543	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
544	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
545	            StringBuilder sb = new StringBuilder(digest.length * 2);
546	            for (byte b : digest) {
547	                sb.append(String.format("%02x", b));
548	            }
549	            return sb.toString();
550	        }
551	        catch (java.security.NoSuchAlgorithmException e) {
552	            throw new IllegalStateException("SHA-256 not available", e);
553	        }
554	    }
