556	    /**
557	     * The American Soundex code of a name: its first letter followed by three digits derived from
558	     * the remaining consonants ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3};
559	     * {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w} are not coded).
560	     * Adjacent letters mapping to the same digit (including when separated only by {@code h} or
561	     * {@code w}) are coded once, while a vowel between them resets the run so the digit is coded
562	     * again. The code is right-padded with zeros and truncated to length four. A {@code null} or
563	     * letter-free name yields {@code '0000'}.
564	     *
565	     * @param name the name to encode
566	     * @return the four-character Soundex code
567	     */
568	    public static String soundex(String name) {
569	        String s = (name == null ? "" : name).toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
570	        if (s.isEmpty()) {
571	            return "0000";
572	        }
573	        char first = s.charAt(0);
574	        StringBuilder code = new StringBuilder().append(first);
575	        char prevDigit = soundexDigit(first);
576	        for (int i = 1; i < s.length() && code.length() < 4; i++) {
577	            char c = s.charAt(i);
578	            char digit = soundexDigit(c);
579	            if (digit != '0' && digit != prevDigit) {
580	                code.append(digit);
581	            }
582	            if (c != 'H' && c != 'W') {
583	                prevDigit = digit;
584	            }
585	        }
586	        while (code.length() < 4) {
587	            code.append('0');
588	        }
589	        return code.toString();
590	    }
591	
592	    /**
593	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
594	     * uncoded letters {@code h} and {@code w}.
595	     *
596	     * @param c the upper-case letter to map
597	     * @return the Soundex digit character, or {@code '0'} when the letter is not coded
598	     */
599	    private static char soundexDigit(char c) {
600	        switch (c) {
601	            case 'B': case 'F': case 'P': case 'V':
602	                return '1';
603	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
604	                return '2';
605	            case 'D': case 'T':
606	                return '3';
607	            case 'L':
608	                return '4';
609	            case 'M': case 'N':
610	                return '5';
611	            case 'R':
612	                return '6';
613	            default:
614	                return '0';
615	        }
616	    }
617	
618	    /**
619	     * A single Luhn check digit (0-9) computed over the digits contained in {@code source}.
620	     * Non-digit characters (such as letter prefixes and separators) are ignored; a {@code null}
621	     * source is treated as having no digits. This is the CHK segment of the owner's
622	     * {@code memberId}, computed over the digits of its {@code <REGION><FY><HASH8>} prefix.
623	     *
624	     * @param source the string whose digits the check digit is computed over
625	     * @return the Luhn check digit (0-9)
626	     */
627	    public static int luhnCheckDigit(String source) {
628	        if (source == null) {
629	            source = "";
630	        }
631	        int sum = 0;
632	        boolean dbl = true;
633	        for (int i = source.length() - 1; i >= 0; i--) {
634	            char c = source.charAt(i);
635	            if (c < '0' || c > '9') {
636	                continue;
637	            }
638	            int d = c - '0';
639	            if (dbl) {
640	                d *= 2;
641	                if (d > 9) {
642	                    d -= 9;
643	                }
644	            }
645	            sum += d;
646	            dbl = !dbl;
647	        }
648	        return (10 - (sum % 10)) % 10;
649	    }
