132	     */
133	    @ExceptionHandler(DataIntegrityViolationException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
136	        logger.warn("Data integrity violation at {} {}: {}",
137	            request.getMethod(),
