139	            e.getMessage());
140	        logger.debug("Data integrity violation stacktrace", e);
141	        HttpStatus status = HttpStatus.NOT_FOUND;
142	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
143	        return ResponseEntity.status(status).body(detail);
144	    }
