7	/**
8	 * Derives an owner's canonical region ("locality"). The postcode is preferred:
9	 * a 4-digit postcode is matched against each region's inclusive range first, and
10	 * only when the postcode is absent or in no known range does derivation fall back
11	 * to a fixed city-to-region table. Kept as a plain utility (rather than a mapper
12	 * method) so MapStruct does not treat it as an implicit {@code String -> String}
13	 * mapping.
14	 */
15	public final class Localities {
16	
17	    /** City -> canonical region. Anything not listed derives {@link #UNKNOWN}. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	        "Sydney", "NSW",
20	        "Melbourne", "VIC",
21	        "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    /** Region -> IANA timezone name. Anything not listed derives a {@code null} timezone. */
30	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
31	        "NSW", "Australia/Sydney",
32	        "VIC", "Australia/Melbourne",
33	        "QLD", "Australia/Brisbane");
34	
35	    /** Region returned for a city that is absent from {@link #CITY_REGION}. */
36	    public static final String UNKNOWN = "UNKNOWN";
37	
38	    private Localities() {
39	    }
40	
41	    /**
42	     * Returns the canonical region for {@code city} from the fixed table
43	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
44	     * or {@code "UNKNOWN"} when the city is {@code null} or not in the table.
45	     *
46	     * @param city the owner's city
47	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
48	     */
49	    public static String forCity(String city) {
50	        if (city == null) {
51	            return UNKNOWN;
52	        }
53	        return CITY_REGION.getOrDefault(city, UNKNOWN);
54	    }
55	
56	    /**
57	     * Returns the canonical region, preferring the {@code postcode}: it is matched
58	     * against each region's inclusive postcode range first (NSW 2000-2099,
59	     * VIC 3000-3099, QLD 4000-4099). Only when the postcode is {@code null},
60	     * non-numeric, or in no known range does derivation fall back to the
61	     * {@link #forCity(String) city-to-region table}. This returns the same region
62	     * for known cities but disambiguates cities that share a name.
63	     *
64	     * @param city the owner's city
65	     * @param postcode the owner's postcode, may be {@code null}
66	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
67	     */
68	    public static String forCityAndPostcode(String city, String postcode) {
69	        String region = forPostcode(postcode);
70	        if (region != null) {
71	            return region;
72	        }
73	        return forCity(city);
74	    }
75	
76	    /**
77	     * Returns the owner's canonical region ("locality"), the plain region derived from the owner's
78	     * city and postcode via {@link #forCityAndPostcode(String, String)}. This is the same base
79	     * region the version-2 identity is built on, but without the {@code 'V2'} version tag: the tag
80	     * appears only inside the identifiers (see {@link #regionCodeV2(String, String)}), never in the
81	     * user-facing locality, timezone or owner segment.
82	     *
83	     * @param owner the owner whose locality is required
84	     * @return the canonical region string, or {@code "UNKNOWN"} when unknown
85	     */
86	    public static String forOwner(Owner owner) {
87	        return forCityAndPostcode(owner.getCity(), owner.getPostcode());
88	    }
89	
90	    /**
91	     * Returns the version-2 region code used <em>inside</em> the owner's identifiers, formed by
92	     * mixing the fixed {@code 'V2'} version tag ({@link Owner#IDENTITY_VERSION_TAG}) into the plain
93	     * canonical region ({@link #forCityAndPostcode(String, String)}). For example a Sydney owner
94	     * (region {@code NSW}) yields {@code 'V2NSW'}. This appears only in identifiers (the memberId's
95	     * region segment); the user-facing {@link #forOwner(Owner) locality} stays the plain region.
96	     *
97	     * @param city     the owner's city
98	     * @param postcode the owner's postcode, may be {@code null}
99	     * @return the version-2 region code
100	     */
101	    public static String regionCodeV2(String city, String postcode) {
102	        return Owner.IDENTITY_VERSION_TAG + forCityAndPostcode(city, postcode);
103	    }
104	
105	    /**
106	     * Returns the owner's segment, formatted {@code "<TIER>_<AREA>"}. TIER is {@code "PREMIUM"}
107	     * when the owner's {@link Owner#effectiveMembershipLevel(Owner) effective membership level} is
108	     * 3 or more, otherwise {@code "STANDARD"}. AREA is {@code "METRO"} when the owner's
109	     * {@link #forOwner(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
110	     * {@code "REGIONAL"}.
111	     *
112	     * @param owner the owner whose segment is required
113	     * @return the segment string, one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
114	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}
115	     */
116	    public static String segmentForOwner(Owner owner) {
117	        String tier = Owner.effectiveMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
118	        String area = REGION_POSTCODES.containsKey(forOwner(owner)) ? "METRO" : "REGIONAL";
119	        return tier + "_" + area;
120	    }
121	
122	    /**
123	     * Returns the IANA timezone name for {@code region} from the fixed region-to-timezone
124	     * table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
125	     * {@code QLD -> Australia/Brisbane}), or {@code null} when the region is {@code null}
126	     * or not in the table (for example {@code "UNKNOWN"}).
127	     *
128	     * @param region the canonical region string
129	     * @return the IANA timezone name, or {@code null} when unknown
130	     */
131	    public static String timezoneForRegion(String region) {
132	        if (region == null) {
133	            return null;
134	        }
135	        return REGION_TIMEZONE.get(region);
136	    }
137	
138	    /**
139	     * Returns the owner's IANA timezone name, derived from the owner's locality/region
140	     * ({@link #forOwner(Owner)}) via the fixed region-to-timezone table, or {@code null}
141	     * when the region is not in the table.
142	     *
143	     * @param owner the owner whose timezone is required
144	     * @return the IANA timezone name, or {@code null} when unknown
145	     */
146	    public static String timezoneForOwner(Owner owner) {
147	        return timezoneForRegion(forOwner(owner));
148	    }
149	
150	    /**
151	     * Returns the region whose inclusive postcode range contains {@code postcode},
152	     * or {@code null} when the postcode is {@code null}, non-numeric, or in no
153	     * known range.
154	     */
155	    private static String forPostcode(String postcode) {
156	        if (postcode == null) {
157	            return null;
158	        }
159	        int value;
160	        try {
161	            value = Integer.parseInt(postcode.trim());
162	        }
163	        catch (NumberFormatException ex) {
164	            return null;
165	        }
166	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
167	            int[] range = entry.getValue();
168	            if (value >= range[0] && value <= range[1]) {
169	                return entry.getKey();
170	            }
171	        }
172	        return null;
173	    }
174	}
